import os
import ast

keywords = ['create_', 'update_', 'delete_', 'save_', 'write_', 'POST', 'PUT', 'PATCH']

def analyze():
    files = []
    for root, _, filenames in os.walk('app'):
        for f in filenames:
            if f.endswith('.py') and f != 'auth.py':
                files.append(os.path.join(root, f))

    files.sort()

    for filepath in files:
        with open(filepath, 'r') as f:
            content = f.read()

        try:
            tree = ast.parse(content)
        except Exception as e:
            print(f"Error parsing {filepath}: {e}")
            continue

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                calls_legacy = False
                for child in ast.walk(node):
                    if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == 'legacy_auth':
                        calls_legacy = True
                        break

                if calls_legacy:
                    lines = content.splitlines()
                    start = node.lineno - 1
                    end = getattr(node, 'end_lineno', len(lines))
                    func_lines = lines[start:end]
                    func_text = '\n'.join(func_lines)

                    matched = []
                    for kw in keywords:
                        if kw in func_text:
                            matched.append(kw)
                        elif kw.lower() in func_text.lower():
                            matched.append(f"{kw} (case-insensitive)")

                    print(f"File: {filepath} | Func: {node.name}")
                    if matched:
                        print(f"  Matched keywords: {matched} -> scope='write'")
                    else:
                        print(f"  No keywords matched -> scope='read'")

if __name__ == '__main__':
    analyze()
